import{z as B,x as d,o as l,c,q as E,j as r,D as n,d as a,s,S as t,b as i}from"./chunks/framework.C8m1ZpeB.js";const h=JSON.parse('{"title":"内核配置与编译","description":"","frontmatter":{"title":"内核配置与编译","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/kernel-config-build.md","filePath":"cs/kernel-config-build.md","lastUpdated":1791413859000}'),A={name:"cs/kernel-config-build.md"};function p(f,e,m,u,C,g){const o=d("Mermaid");return l(),c("div",null,[e[2]||(e[2]=E('<h1 id="内核配置与编译" tabindex="-1">内核配置与编译 <a class="header-anchor" href="#内核配置与编译" aria-label="Permalink to &quot;内核配置与编译&quot;">​</a></h1><div class="epigraph"><p>Kconfig 决定哪些子系统编进内核或模块；.config 是构建输入，决定 [PREEMPT_RT](/cs/preempt-rt)、[KPTI](/cs/kpti-os)、调试选项是否存在。</p><footer>—— 据 Linux kbuild/Kconfig 文档；[cmdline](/cs/kernel-cmdline) 为运行时对照</footer></div><p><a href="/cs/livepatch">livepatch</a> 假定有匹配的二进制。<a href="/cs/kernel-hardening">加固</a> 是一组 CONFIG。缺口是 <strong>配置与编译</strong>：不是发行版包管理百科。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p><code>make menuconfig</code>：三态 y/m/n。缺口：依赖与 select；localmodconfig；调试 on 则性能与大小变。本课不把全部符号当词典。</p><p><span class="marginnote">发行版提供预置 config。自编译要匹配 gcc 与 ABI——下一课 kABI。对象是构建系统。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>.config → kbuild 编 vmlinux/modules → 安装 + initramfs。对照 <a href="/cs/systemd-units">systemd</a>：用户态构建另一套。对照 DT：DTB 可独立于内核镜像。对照 ASan：<code>CONFIG_KASAN</code> 是开发配置。</p>',8)),(l(),r(t,null,{default:n(()=>[s(o,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20KC%5B%22Kconfig%22%5D%20--%3E%20CFG%5B%22.config%22%5D%0A%20%20CFG%20--%3E%20KB%5B%22kbuild%22%5D%0A%20%20KB%20--%3E%20IMG%5B%22vmlinux%20%E4%B8%8E%E6%A8%A1%E5%9D%97%22%5D%0A"})]),fallback:n(()=>[...e[0]||(e[0]=[a(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=i("h2",{id:"机制",tabindex:"-1"},[a("机制 "),i("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),e[4]||(e[4]=i("p",null,[a("Kconfig 把内核变成可裁剪的产品族，使嵌入式与服务器分享源码。错误的 n 会让驱动不存在，表现为 udev 无节点。不要写成编译原理课。与 "),i("a",{href:"/cs/eas-scheduling"},"EAS"),a("：无 CONFIG 则无该调度。")],-1)),e[5]||(e[5]=i("p",null,"模块与内建的取舍影响启动与攻击面。",-1)),(l(),r(t,null,{default:n(()=>[s(o,{id:"mermaid-32",class:"mermaid",graph:"flowchart%20TD%0A%20%20SYM%7B%22%E4%B8%80%E4%B8%AA%E5%8A%9F%E8%83%BD%E9%80%89%E4%BB%80%E4%B9%88%EF%BC%9F%22%7D%0A%20%20SYM%20--%3E%7C%22y%20%E5%86%85%E5%BB%BA%22%7C%20B%5B%22%E7%BC%96%E8%BF%9B%20vmlinux%EF%BC%9A%E5%BC%80%E6%9C%BA%E5%8D%B3%E6%9C%89%EF%BC%8C%E5%88%A0%E4%B8%8D%E6%8E%89%22%5D%0A%20%20SYM%20--%3E%7C%22m%20%E6%A8%A1%E5%9D%97%22%7C%20M%5B%22%E7%8B%AC%E7%AB%8B%20.ko%EF%BC%9A%E6%8C%89%E9%9C%80%E5%8A%A0%E8%BD%BD%EF%BC%8C%E5%8F%AF%E9%BB%91%E5%90%8D%E5%8D%95%22%5D%0A%20%20SYM%20--%3E%7C%22n%20%E4%B8%8D%E7%BC%96%22%7C%20N%5B%22%E4%BA%8C%E8%BF%9B%E5%88%B6%E9%87%8C%E6%A0%B9%E6%9C%AC%E6%B2%A1%E6%9C%89%EF%BC%9A%E6%97%A0%E6%94%BB%E5%87%BB%E9%9D%A2%E4%B9%9F%E6%97%A0%E5%8A%9F%E8%83%BD%22%5D%0A%20%20B%20--%3E%20T%5B%22%E5%90%AF%E5%8A%A8%E6%97%A9%E6%9C%9F%EF%BC%88%E5%A6%82%E6%A0%B9%E6%96%87%E4%BB%B6%E7%B3%BB%E7%BB%9F%E9%A9%B1%E5%8A%A8%EF%BC%89%E5%8F%AA%E8%83%BD%E9%80%89%20y%22%5D%0A%20%20M%20--%3E%20T2%5B%22%E5%A4%A7%E8%80%8C%E5%B0%91%E7%94%A8%E7%9A%84%E9%A9%B1%E5%8A%A8%E9%80%89%20m%20%E7%9C%81%E5%B8%B8%E9%A9%BB%E5%86%85%E5%AD%98%22%5D%0A"})]),fallback:n(()=>[...e[1]||(e[1]=[a(" Loading... ",-1)])]),_:1})),e[6]||(e[6]=E('<p><span class="marginnote">术语翻译：Kconfig 的三态 y/m/n 就是「烤进蛋糕 / 做成加件 / 不做」——y 编进内核镜像本体，m 编成可插拔的 .ko 模块文件，n 则完全不编译。每个符号背后是一个功能或驱动。</span></p><p><span class="marginnote">数字实例：开 <code>CONFIG_DEBUG_INFO</code> 前后，vmlinux 可从几十 MB 涨到数百 MB——调试信息（DWARF）比代码本身大得多，但 perf、崩栈解析全靠它。开发机常开，生产镜像常关，这就是「调试选项改变二进制」的具体分量。</span></p><p><span class="marginnote">直觉类比：Kconfig 的依赖关系像点套餐——没点主菜（如 <code>CONFIG_PCI=n</code>）， depend 它的配菜（网卡驱动）直接从菜单上消失；而 <code>select</code> 是反向的「套餐强制含配菜」，选了它就自动替你勾上依赖项，这也是配置打架的常见来源。</span></p><p>实现上：localmodconfig 按当前已加载模块裁剪，换硬件要重配。DEBUG_INFO 让 vmlinux 巨大但 perf 才好用。发行版 config 是产品选择，不是「完整内核」。 读法上只引用<a href="/cs/livepatch">上一课</a>的结论，不把对象换成训练推理或限价簿。</p><p>本课在操作系统进阶的「安全、启动与调试 / 观测与调试」课序里，对象是 <strong>内核配置与编译</strong>。</p><ul><li>先修只引用，不重导：上一课的结论当公理，本课只补差。</li><li>五栏不吞并：不把本课写成大模型训练/推理，也不写成限价簿或权重量化。</li><li>文献用 OSTEP、McKusick、内核文档与具名会议论文；不发明 arXiv 编号。</li></ul><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入所有交叉编译工具链。不保证 reproducible build 的每一步。下一课加载后的兼容：kABI 与模块签名。</p><p>版本字段会变，课序钉的是机制对象「内核配置与编译」，不是某一主线内核的结构体名。 后课默认：功能由 .config 决定。模块 ABI 与签名，下一课。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>Kconfig 生成 .config，kbuild 产出内核与模块。</li><li>调试与加固选项改变二进制。</li><li>kABI 与模块签名是下一课。</li><li>出处：kbuild；Kconfig；内核 README。</li></ul>',11))])}const k=B(A,[["render",p]]);export{h as __pageData,k as default};
